def relabeled_clone(self, relabels):
    # First, clone the query to ensure we're not altering the original
    clone = self.clone()

    # Relabel the aliases in the clone query
    clone.relabel_aliases(relabels)

    # Recursively relabel any annotations or expressions
    if clone.annotations:
        clone.annotations = {key: annotation.relabeled_clone(relabels)
                             for key, annotation in clone.annotations.items()}

    # Handle relabeling within subqueries and various clauses
    if clone.select:
        clone.select = [sel.relabeled_clone(relabels) for sel in clone.select]

    if clone.where:
        clone.where = clone.where.relabeled_clone(relabels)

    if clone.group_by:
        clone.group_by = [gb.relabeled_clone(relabels) for gb in clone.group_by]

    if clone.order_by:
        clone.order_by = [ob.relabeled_clone(relabels) for ob in clone.order_by]

    # If there are subqueries, relabel them as well
    if hasattr(clone, 'subqueries'):
        clone.subqueries = [subquery.relabeled_clone(relabels) for subquery in clone.subqueries]

    # Return the modified clone
    return clone
